<?php use App\Core\Csrf; ?>
<div class="page-heading"><div><p class="eyebrow">Monitoring</p><h1>Teacher attendance</h1><p>Record the daily attendance of active teaching staff.</p></div><a class="button" href="<?=e(url('/attendance/students'))?>">Student attendance</a></div>
<form method="get" class="filter-bar date-filter"><label>Date<input type="date" name="date" required value="<?=e($date)?>"></label><button class="button primary">Load attendance</button></form>
<form method="post" action="<?=e(url('/attendance/teachers'))?>"><?=Csrf::field()?><input type="hidden" name="date" value="<?=e($date)?>"><section class="card table-card"><div class="table-heading"><div><h2><?=e($date)?></h2><small><?=count($teachers)?> active staff records</small></div><?php if($canRecord):?><button type="button" class="button small" data-mark-present>Mark all present</button><?php endif;?></div><table class="attendance-table"><thead><tr><th scope="col">Teacher</th><th scope="col">Status</th><th scope="col">Time in</th><th scope="col">Time out</th><th scope="col">Remarks</th></tr></thead><tbody><?php foreach($teachers as $t):?><tr><td><strong><?=e($t['last_name'].', '.$t['first_name'])?></strong><br><small><?=e($t['employee_no'].' · '.($t['department']??'No department'))?></small></td><td><select name="attendance[<?=$t['id']?>][status]" <?=$canRecord?'':'disabled'?> class="status-select"><?php foreach($statuses as $status):?><option value="<?=$status?>" <?=$t['attendance_status']===$status?'selected':''?>><?=e(ucwords(str_replace('_',' ',$status)))?></option><?php endforeach;?></select></td><td><input type="time" name="attendance[<?=$t['id']?>][time_in]" value="<?=e(substr((string)$t['time_in'],0,5))?>" <?=$canRecord?'':'disabled'?>></td><td><input type="time" name="attendance[<?=$t['id']?>][time_out]" value="<?=e(substr((string)$t['time_out'],0,5))?>" <?=$canRecord?'':'disabled'?>></td><td><input name="attendance[<?=$t['id']?>][remarks]" value="<?=e($t['remarks'])?>" maxlength="500" <?=$canRecord?'':'disabled'?>></td></tr><?php endforeach;?><?php if(!$teachers):?><tr><td colspan="5" class="empty">No active teachers found.</td></tr><?php endif;?></tbody></table></section><?php if($canRecord&&$teachers):?><div class="sticky-actions"><button class="button primary">Save teacher attendance</button></div><?php endif;?></form>
<script>document.querySelector('[data-mark-present]')?.addEventListener('click',()=>document.querySelectorAll('.status-select').forEach(x=>x.value='present'));</script>
